/*${HSMs::Clock_Alarm::SM::Clock::Settings::Clock_Setting::cs_format} ......*/
static QState Clock_Alarm_cs_format(Clock_Alarm * const me, QEvt const * const e) {
    QState status_;
    switch (e->sig) {
        /*${HSMs::Clock_Alarm::SM::Clock::Settings::Clock_Setting::cs_format} */
        case Q_ENTRY_SIG: {
            display_set_cursor(CLOCK_SETTING_TIME_ROW, CLOCK_SETTING_TIME_FMT_COL);
            const char *msg[3] = {"24H", "AM ", "PM "};
            display_write(msg[me->temp_format], CLOCK_SETTING_TIME_ROW, CLOCK_SETTING_TIME_FMT_COL);
            display_set_cursor(CLOCK_SETTING_TIME_ROW, CLOCK_SETTING_TIME_FMT_COL);
            status_ = Q_HANDLED();
            break;
        }
        /*${HSMs::Clock_Alarm::SM::Clock::Settings::Clock_Setting::cs_format::SET} */
        case SET_SIG: {
            const char *msg;
            if (me->temp_format == FORMAT_24H) {
                me->temp_format = FORMAT_AM;
                msg = "AM ";
            } else if (me->temp_format == FORMAT_AM) {
                me->temp_format = FORMAT_PM;
                msg = "PM ";
            } else if (me->temp_format == FORMAT_PM) {
                me->temp_format = FORMAT_24H;
                msg = "24H";
            } else {
                me->temp_format = FORMAT_24H;
                msg = "24H";
            }
            display_write(msg, CLOCK_SETTING_TIME_ROW, CLOCK_SETTING_TIME_FMT_COL);
            display_set_cursor(CLOCK_SETTING_TIME_ROW, CLOCK_SETTING_TIME_FMT_COL);
            status_ = Q_HANDLED();
            break;
        }
        /*${HSMs::Clock_Alarm::SM::Clock::Settings::Clock_Setting::cs_format::OK} */
        case OK_SIG: {
            /*${HSMs::Clock_Alarm::SM::Clock::Settings::Clock_Setting::cs_format::OK::[is_time_set_error(me->temp_time~} */
            if (is_time_set_error(me->temp_time,(time_format_t)me->temp_format)) {
                status_ = Q_TRAN(&Clock_Alarm_cs_error);
            }
            else {
                status_ = Q_UNHANDLED();
            }
            break;
        }
        default: {
            status_ = Q_SUPER(&Clock_Alarm_Clock_Setting);
            break;
        }
    }
    return status_;
}

/*${HSMs::Clock_Alarm::SM::Clock::Settings::Clock_Setting::cs_error} .......*/
static QState Clock_Alarm_cs_error(Clock_Alarm * const me, QEvt const * const e) {
    QState status_;
    switch (e->sig) {
        /*${HSMs::Clock_Alarm::SM::Clock::Settings::Clock_Setting::cs_error} */
        case Q_ENTRY_SIG: {
            display_cursor_off_blinkoff();
            display_erase_block(ALARM_SETTING_CURR_TIME_ROW, 0, LCD_COLS - 1);
            me->timeout = 0;
            status_ = Q_HANDLED();
            break;
        }
        /*${HSMs::Clock_Alarm::SM::Clock::Settings::Clock_Setting::cs_error} */
        case Q_EXIT_SIG: {
            display_erase_block(CLOCK_SETTING_ERR_MSG_ROW,CLOCK_SETTING_ERR_MSG_COL,CLOCK_SETTING_ERR_MSG_COL_END);
            me->timeout = 0;
            status_ = Q_HANDLED();
            break;
        }
        /*${HSMs::Clock_Alarm::SM::Clock::Settings::Clock_Setting::cs_error::initial} */
        case Q_INIT_SIG: {
            status_ = Q_TRAN(&Clock_Alarm_err_on);
            break;
        }
        /*${HSMs::Clock_Alarm::SM::Clock::Settings::Clock_Setting::cs_error::SET} */
        case SET_SIG: {
            display_cursor_on_blinkon();
            status_ = Q_TRAN(&Clock_Alarm_Clock_Setting);
            break;
        }
        /*${HSMs::Clock_Alarm::SM::Clock::Settings::Clock_Setting::cs_error::OK} */
        case OK_SIG: {
            status_ = Q_HANDLED();
            break;
        }
        default: {
            status_ = Q_SUPER(&Clock_Alarm_Clock_Setting);
            break;
        }
    }
    return status_;
}

/*${HSMs::Clock_Alarm::SM::Clock::Settings::Clock_Setting::cs_error::err_on}*/
static QState Clock_Alarm_err_on(Clock_Alarm * const me, QEvt const * const e) {
    QState status_;
    switch (e->sig) {
        /*${HSMs::Clock_Alarm::SM::Clock::Settings::Clock_Setting::cs_error::err_on} */
        case Q_ENTRY_SIG: {
            display_write("Error!",CLOCK_SETTING_ERR_MSG_ROW,CLOCK_SETTING_ERR_MSG_COL);
            status_ = Q_HANDLED();
            break;
        }
        /*${HSMs::Clock_Alarm::SM::Clock::Settings::Clock_Setting::cs_error::err_on::TICK} */
        case TICK_SIG: {
            ++me->timeout;
            /*${HSMs::Clock_Alarm::SM::Clock::Settings::Clock_Setting::cs_error::err_on::TICK::[me->timeout==10]} */
            if (me->timeout == 10) {
                me->timeout = 0;
                status_ = Q_TRAN(&Clock_Alarm_err_off);
            }
            else {
                status_ = Q_UNHANDLED();
            }
            break;
        }
        default: {
            status_ = Q_SUPER(&Clock_Alarm_cs_error);
            break;
        }
    }
    return status_;
}

